// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    // fuzzed params: deposit amount and a flag selecting whether the callee will re-enter
    function testFuzz_property(uint128 depositAmount, bool attackerDoesReenter) public {
        // keep depositAmount within reasonable bounds and non-zero to exercise withdraw
        uint256 amount = bound(depositAmount, 1, 1 ether);

        // deploy an attacker contract that can reenter exactly once
        Attacker attacker = new Attacker(c);

        // fund attacker so it can deposit
        vm.deal(address(attacker), amount);

        // attacker deposits into c
        attacker.deposit{value: amount}();

        // Ensure attacker has the intended credit recorded in c by observing behavior of deposit
        // (deposit is simple and will succeed)

        // Now attempt withdrawAll from attacker. If attackerDoesReenter is true, configure it to reenter during the external call.
        attacker.setReenter(attackerDoesReenter);

        // call withdrawAll as the attacker (the external call in c will hit attacker's receive and potentially reenter)
        bool ok;
        try attacker.callWithdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdrawAll returns successfully, the correct contract guarantees attacker's recorded credit is zero.
        // We read the contract's storage via the auto-generated public getter: credit is private in original contract, so
        // cannot read it directly. However, we can infer credit remaining by calling withdrawAll again and seeing if any value
        // is sent (second withdraw should be a no-op if credit is zero). To do that, make a fresh helper that records receipts.

        // Deploy a Recorder to observe whether any funds are sent on a second withdraw attempt.
        Recorder rec = new Recorder();
        // Transfer any remaining ether from attacker to rec so rec can be the msg.sender for the second withdraw attempt.
        // But withdrawAll sends to msg.sender, so we need the attacker address to be the callee. We'll have the attacker perform
        // a second withdraw and forward any received funds to rec for observation.
        attacker.setForwardTarget(address(rec));

        // Prepare attacker to NOT reenter on the second call
        attacker.setReenter(false);

        // Call withdrawAll a second time through attacker and let attacker forward any received value to Recorder
        try attacker.callWithdrawAllAndForward() {
            ok = ok && true;
        } catch {
            ok = false;
        }

        // If the correct contract executed, there should be nothing left to withdraw; Recorder should have recorded 0 value received.
        // For the mutant (vulnerable to reentrancy) there exist inputs where attacker reentered during the first withdraw and
        // left its credit nonzero; then the second withdraw will send remaining funds and Recorder will observe a nonzero value.
        uint256 recorded = rec.totalReceived();

        // The universal property: for all admissible inputs, if the first withdrawAll completed successfully, then no funds remain
        // to be withdrawn (recorder sees zero on the second withdraw). This holds in the reference but is violated by the mutant
        // for some (found by fuzzing) where attackerDoesReenter==true and depositAmount large enough.
        assertTrue(ok && recorded == 0);
    }
}

// Attacker contract: can deposit, call withdrawAll, optionally reenter once during receive,
// and forward any later receipts to a recorder for observation.
contract Attacker {
    ReentrancyDAO immutable c;
    bool public doReenter;
    bool private __entered;
    address public forwardTarget;

    constructor(ReentrancyDAO _c) {
        c = _c;
    }

    // receive will optionally reenter c.withdrawAll exactly once
    receive() external payable {
        if (doReenter && !__entered) {
            __entered = true;
            // reenter withdrawAll while original withdraw is in progress
            c.withdrawAll();
        }
        // if a forward target is set, forward received ETH to it so it can record receipts
        if (forwardTarget != address(0)) {
            (bool s, ) = forwardTarget.call{value: msg.value}("");
            require(s);
        }
    }

    function deposit() external payable {
        // deposit into c from this contract
        c.deposit{value: msg.value}();
    }

    function setReenter(bool r) external {
        doReenter = r;
        __entered = false;
    }

    function callWithdrawAll() external {
        // call withdrawAll so that c will send to this contract and potentially reenter
        c.withdrawAll();
    }

    function setForwardTarget(address t) external {
        forwardTarget = t;
    }

    function callWithdrawAllAndForward() external {
        // call withdrawAll again; any funds received will be forwarded in receive()
        c.withdrawAll();
    }
}

// Recorder contract: records total value received through payable fallback/receive
contract Recorder {
    uint256 public total;
    receive() external payable { total += msg.value; }
    function totalReceived() external view returns (uint256) { return total; }
}
